    double aktiviere(double pWert);
}
```

```java Sigmoid.java
public class Sigmoid implements Aktivierung {
    public double aktiviere(double pWert) {
        return 1.0 / (1.0 + Math.exp(-pWert));
    }
}
```

```java ReLU.java
public class ReLU implements Aktivierung {
    public double aktiviere(double pWert) {
        if (pWert < 0) {
            return 0.0;
        }
        return pWert;
    }
}
```

