  FROM auftritt AS a
  JOIN band AS b ON b.band_id = a.band_id
 GROUP BY b.name
HAVING COUNT(*) >= 3
 ORDER BY b.name;

-- c) 5 Genres: Indie, Rock, Elektro, Metal und Folk
