  FROM band_genre AS bg
  JOIN genre AS g ON g.genre_id = bg.genre_id
 GROUP BY g.name
HAVING COUNT(*) >= 4
 ORDER BY bands DESC;

-- d) 2 Bühnen: Hauptbuehne und Waldbuehne
