```java
void main() {
    for (int i = 1; i <= 4; i++) {
        String zeile = "";
        for (int j = 1; j <= i; j++) {
            zeile = zeile + "*";
        }
        IO.println(zeile);
    }

    IO.println("");

    for (int zeile = 1; zeile <= 3; zeile++) {
        String ausgabe = "";
        for (int spalte = 1; spalte <= 4; spalte++) {
            ausgabe = ausgabe + (zeile * spalte) + "\t";
