```java Woerter.java
public class Woerter {

    /**
     * Prüft, ob pWort vorwärts wie rückwärts gelesen gleich ist.
     */
    public boolean istPalindrom(String pWort) {
        int links = 0;
        int rechts = pWort.length() - 1;

        while (links < rechts) {
            if (pWort.charAt(links) != pWort.charAt(rechts)) {
                return false;
            }
            links++;
            rechts--;
        }
        return true;
    }
}
```

