public class Statistik {

    public String punkteInNote(int pPunkte) {
        if (pPunkte >= 13) {
            return "sehr gut";
        } else if (pPunkte >= 10) {
            return "gut";
        } else if (pPunkte >= 7) {
            return "befriedigend";
        } else if (pPunkte >= 4) {
            return "ausreichend";
        } else if (pPunkte >= 1) {
            return "mangelhaft";
        } else {
            return "ungenügend";
        }
    }

    public double durchschnitt(int pA, int pB, int pC) {
        return (double) (pA + pB + pC) / 3;
    }

    public int maximum(int pA, int pB, int pC) {
        int groesstes = pA;
        if (pB > groesstes) {
            groesstes = pB;
        }
        if (pC > groesstes) {
            groesstes = pC;
        }
        return groesstes;
    }

    public boolean istBestanden(double pSchnitt) {
        return pSchnitt >= 5.0;
    }
}
