        leben = 3;
        unverwundbar = false;
    }

    public String getName() {
        return name;
    }

    public int getLeben() {
        return leben;
    }

    public void bewege(double pDx, double pDy) {
        x = x + pDx;
        y = y + pDy;
    }

    public boolean erleideSchaden(int pMenge) {
        if (unverwundbar) {
            return false;
        }
        leben = leben - pMenge;
        pruefeLeben();
        return true;
    }

    private void pruefeLeben() {
        if (leben < 0) {
            leben = 0;
        }
    }
}
```

