/** Liefert ein sortiertes Feld mit den Werten 0, 2, 4, ... */
int[] sortiertesFeld(int pAnzahl) {
    int[] feld = new int[pAnzahl];
    for (int i = 0; i < pAnzahl; i++) {
        feld[i] = i * 2;
