funktion kopie(pStapel):
    hilf = neuer Stapel
    kopie = neuer Stapel
    wiederhole solange nicht pStapel.isEmpty():
        hilf.push(pStapel.top())
        pStapel.pop()
    wiederhole solange nicht hilf.isEmpty():
