```
funktion enthaelt(pSchlange, pGesucht):
    hilf = neue Schlange
    gefunden = falsch
    wiederhole solange nicht pSchlange.isEmpty():
        vorne = pSchlange.front()
        pSchlange.dequeue()
        falls vorne.equals(pGesucht):
            gefunden = wahr
        sonst:
        hilf.enqueue(vorne)
    wiederhole solange nicht hilf.isEmpty():
        pSchlange.enqueue(hilf.front())
        hilf.dequeue()
