```java Welt.java
/**
 * Das Spielfeld.
 */
public class Welt extends Stage {

   private static final int MAX_VERSUCHE = 20;

   private SpielerDonut spieler;

   public Welt() {
      this.setColor(250, 245, 235);
      Gitter gitter = new Gitter(3000);
      gitter.zeichneAuf(this);

      spieler = new SpielerDonut();
      this.add(spieler);

      this.getCamera().setZoomLimit(30, 200);
   }

   public void run() {
      if (this.getTimer().every(1)) {
         this.erzeugeFutter();
      }

      Camera kamera = this.getCamera();
      double zielZoom = 1000.0 / spieler.getStaerke();
      if (kamera.getZoom() > zielZoom) {
         kamera.changeZoom(-0.1);
      }
      kamera.setPosition(spieler.getPosition());
   }

   /**
    * Setzt einen kleinen Donut irgendwo in den sichtbaren Bereich, aber nicht auf den Spieler.
    * Findet sich nach MAX_VERSUCHE Würfen keine freie Stelle, fällt das Futter aus.
    */
   private void erzeugeFutter() {
      Donut futter = new Donut(0, 0, Random.randomInt(2, 5));
      this.add(futter);
      Camera kamera = this.getCamera();
      double faktor = 100 / kamera.getZoom();
      int versuche = 0;
      do {
         futter.setPosition(kamera.getX() + Random.random(-400, 400) * faktor,
                            kamera.getY() + Random.random(-300, 300) * faktor);
         versuche++;
      } while (futter.isTouchingSprite(spieler) && versuche < MAX_VERSUCHE);

      if (futter.isTouchingSprite(spieler)) {
         futter.remove();
      }
   }
}

```

```java Gitter.java
/**
 * Ein Gitter aus Linien, das mit einem Stift auf eine Bühne gezeichnet wird.
 */
public class Gitter {

   private static final int ABSTAND = 40;

   private int grenze;

   /**
    * @param pGrenze das Gitter reicht von -pGrenze bis pGrenze, waagerecht wie senkrecht
    */
   public Gitter(int pGrenze) {
      grenze = pGrenze;
   }

   /**
    * Zeichnet das Gitter und einen dicken Rand auf pBuehne.
    */
   public void zeichneAuf(Stage pBuehne) {
      Pen stift = new Pen();
      pBuehne.add(stift);

      stift.setColor(210, 205, 195);
      stift.setSize(2);
      for (int i = -grenze; i <= grenze; i += ABSTAND) {
         this.linie(stift, i, -grenze, i, grenze);
         this.linie(stift, -grenze, i, grenze, i);
      }

      stift.setColor(200, 100, 100);
      stift.setSize(8);
      stift.setPosition(-grenze, -grenze);
      stift.down();
      stift.setPosition(grenze, -grenze);
      stift.setPosition(grenze, grenze);
      stift.setPosition(-grenze, grenze);
      stift.setPosition(-grenze, -grenze);
      stift.up();
   }

   private void linie(Pen pStift, double pX1, double pY1, double pX2, double pY2) {
      pStift.up();
      pStift.setPosition(pX1, pY1);
      pStift.down();
      pStift.setPosition(pX2, pY2);
      pStift.up();
   }
}

