  public void run() {
    if (this.ziel != null && this.isMouseDown()) {
      this.ziel.setPosition(this.getMouseX(), this.getMouseY());
    }
    if (this.population != null) {
      if (this.zeit >= this.lebenszeit) {
        this.zeit = 0;
