   private String[] sprueche = {
      "Schöner Tag!",
      "Hinter dem Felsen liegt etwas.",
      "Heute alles ausverkauft."
   };
   private Sprite haendler;

   public Beispiel() {
      haendler = this.figur("bunny1_stand", 0, -40, 30);
