   private void markiere(int z, int s) {
      if (z < 0 || z >= plan.length || s < 0 || s >= plan[z].length()) return;
      if (plan[z].charAt(s) == '#' || besucht[z][s]) return;
      besucht[z][s] = true; // Vor den rekursiven Aufrufen markieren!
      this.markiere(z - 1, s);
      this.markiere(z + 1, s);
      this.markiere(z, s - 1);
      this.markiere(z, s + 1);
   }
}

